-- Real rows of the hourly archive (scripts/build-climat-h.py): three stations, October 2026 up to the 24th at 8 h.
CREATE TABLE IF NOT EXISTS postes (poste TEXT PRIMARY KEY, nom TEXT NOT NULL, lat REAL NOT NULL, lon REAL NOT NULL, alt INTEGER, debut INTEGER NOT NULL, fin INTEGER NOT NULL, params TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS heures (poste TEXT NOT NULL, mois INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (poste, mois)) WITHOUT ROWID;
